mapper.select:
SELECT

FROM FLOW_HIS_TASK fht
LEFT JOIN FLOW_DEFINITION fd ON fht.DEFINITION_ID=fd.ID
LEFT JOIN FLOW_INSTANCE fi ON fht.INSTANCE_ID=fi.ID


        AND fht.DEFINITION_ID = #{p.definitionId}


        AND fht.INSTANCE_ID = #{p.instanceId}


        AND fht.TASK_ID = #{p.taskId}


        AND fht.NODE_CODE = #{p.nodeCode}


        AND fht.NODE_NAME = #{p.nodeName}


        AND fht.NODE_TYPE = #{p.nodeType}


        AND fht.TARGET_NODE_CODE = #{p.targetNodeCode}


        AND fht.TARGET_NODE_NAME = #{p.targetNodeName}


        AND fht.APPROVER = #{p.approver}


        AND fht.COOPERATE_TYPE = #{p.cooperateType}


        AND fht.COLLABORATOR = #{p.collaborator}


        AND fht.SKIP_TYPE = #{p.skipType}


        AND fht.FLOW_STATUS = #{p.flowStatus}


        AND fht.FORM_CUSTOM = #{p.formCustom}


        AND fht.FORM_PATH = #{p.formPath}


        AND fht.MESSAGE = #{p.message}


        AND fht.VARIABLE = #{p.variable}


        AND fht.EXT = #{p.ext}


        AND fht.DEL_FLAG = #{p.delFlag}


        AND fht.TENANT_ID = #{p.tenantId}


        AND fht.ID = #{p.id}


        AND fht.CREATE_TIME = #{p.createTime}


        AND fht.UPDATE_TIME = #{p.updateTime}



        AND fd.FLOW_NAME like CONCAT('%',#{p.flowName},'%')


        AND fi.BUSINESS_ID = #{p.businessId}


ORDER BY fht.UPDATE_TIME DESC
